    String version(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "—";}}
    @Override public void dump(String prefix,java.io.FileDescriptor fd,PrintWriter writer,String[] args){
        if(args==null||!Arrays.asList(args).contains("--tmu-stats")){writer.println("TMU: use --tmu-stats for non-sensitive sampling diagnostics");return;}
        try{JSONObject stats=new JSONObject().put("version",version()).put("foreground",visible).put("view",view).put("detail",detail).put("processHost",processHost).put("inFlight",inFlight).put("cpuTimeMs",android.os.Process.getElapsedCpuTime()).put("animationEnabled",ValueAnimator.areAnimatorsEnabled()).put("activeAnimations",visualAnimations.size()).put("animatedDrawFrames",animatedDrawFrames);JSONArray data=new JSONArray();for(Map.Entry<String,JSONObject> entry:hosts.entrySet()){JSONObject h=entry.getValue();JSONObject sample=new JSONObject().put("id",entry.getKey()).put("online",h.optBoolean("online")).put("sampledAt",h.opt("sampledAt"));for(String[] field:new String[][]{{"cpu","cpu","usage"},{"memory","memory","percent"},{"temperature","power","temperature"},{"power","power","cpu"}}){double n=value(obj(h,field[1]),field[2]);sample.put(field[0],Double.isFinite(n)?n:JSONObject.NULL);}data.put(sample);}stats.put("hosts",data);writer.println("TMU_STATS "+stats);}catch(JSONException e){writer.println("TMU_STATS unavailable");}
    }
