    @Override public void onCreate(Bundle state){super.onCreate(state);endpoint=getPreferences(0).getString("endpoint","");token=Vault.load(this);refreshMs=getPreferences(0).getInt("refresh",5000);if(!Arrays.asList(5000,10000,30000).contains(refreshMs))refreshMs=5000;buildShell();if(endpoint.isEmpty()||token.isEmpty())view="settings";renderPage();}
    @Override protected void onResume(){super.onResume();visible=true;ui.removeCallbacks(tick);ui.post(tick);}
    @Override protected void onStop(){visible=false;stopVisualAnimations();generation++;for(ArrayList<Float> h:history.values())if(!h.isEmpty()&&!Float.isNaN(h.get(h.size()-1)))h.add(Float.NaN);ui.removeCallbacks(tick);HttpURLConnection c=connection;if(c!=null)c.disconnect();super.onStop();}
    @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
    @Override public void onBackPressed(){navigateBack();}
    void navigateBack(){if(!detail.isEmpty()){detail="";renderPage();return;}if(!view.equals("overview")){navigate("overview");return;}super.onBackPressed();}
    void syncBackNavigation(){if(Build.VERSION.SDK_INT<33)return;boolean intercept=!detail.isEmpty()||!view.equals("overview");if(intercept&&!backRegistered){backCallback=BackApi33.register(this,()->navigateBack());backRegistered=true;}else if(!intercept&&backRegistered){BackApi33.unregister(this,backCallback);backCallback=null;backRegistered=false;}}

    static final class BackApi33 {
        static Object register(Activity activity,Runnable action){OnBackInvokedCallback callback=action::run;activity.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(OnBackInvokedDispatcher.PRIORITY_DEFAULT,callback);return callback;}
        static void unregister(Activity activity,Object callback){activity.getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback((OnBackInvokedCallback)callback);}
    }
    void openProcesses(String id){if(!id.equals(processHost)){procData=null;query="";}processHost=id;navigate("processes");}
