    void header(){header.removeAllViews();LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView title=strong(detail.isEmpty()?(view.equals("processes")?"进程":view.equals("settings")?"连接与设置":"三端总览"):"‹ "+name(detail),26,TEXT);title.setOnClickListener(v->{if(!detail.isEmpty()){detail="";renderPage();}});row.addView(title,new LinearLayout.LayoutParams(0,-2,1));row.addView(button("刷新",()->{generation++;pollSoon();}));header.addView(row);gap(header,9);status=text("",12,MUTED);header.addView(status);updateStatus();nav.removeAllViews();String[][] tabs={{"overview","◫  总览"},{"processes","≡  进程"},{"settings","⚙  设置"}};for(String[]tab:tabs){TextView t=button(tab[1],()->navigate(tab[0]));t.setTextColor(view.equals(tab[0])?BG:MUTED);t.setBackground(background(view.equals(tab[0])?ACCENT:BG,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(44),1);p.setMargins(dp(3),0,dp(3),0);nav.addView(t,p);}}
    void updateStatus(){if(status==null)return;if(view.equals("settings")){status.setText("三端任务管理器 "+version()+" · Android 16");return;}if(!message.isEmpty()){status.setText(message);status.setTextColor(BAD);return;}if(receivedAt==0){status.setText(endpoint.isEmpty()?"先导入连接文件，开始查看你的设备":"正在连接采集中心…");return;}int online=0;for(JSONObject h:hosts.values())if(h.optBoolean("online"))online++;status.setText(online+" / 3 台在线 · "+new SimpleDateFormat("HH:mm:ss",Locale.CHINA).format(new Date(receivedAt))+" 更新 · "+(refreshMs/1000)+" 秒刷新");status.setTextColor(MUTED);}
    void navigate(String target){detail="";view=target;generation++;message="";HttpURLConnection c=connection;if(c!=null)c.disconnect();renderPage();pollSoon();}
    void renderPage(){stopVisualAnimations();syncBackNavigation();header();body.removeAllViews();processList=null;processAdapter=null;search=null;scroll.setVisibility(View.VISIBLE);if(view.equals("settings")){settings();return;}if(view.equals("processes")){processPage();return;}overview();}
    void overview(){stopVisualAnimations();body.removeAllViews();if(!detail.isEmpty()){details(detail);return;}TextView intro=text("三台设备 · 实时状态",14,MUTED);intro.setLineSpacing(dp(5),1);intro.setPadding(dp(4),dp(3),0,dp(12));body.addView(intro);for(String id:new String[]{"mac","n100","win11"})card(id);if(endpoint.isEmpty())body.addView(button("配置我的采集中心",()->navigate("settings")));else{TextView note=text("设备离线时如实显示缺失。温度与功耗按各设备的可读能力提供。",12,MUTED);note.setPadding(dp(4),dp(9),0,0);body.addView(note);}}
    String name(String id){return id.equals("mac")?"MacBook":id.equals("n100")?"N100":"Win 11";}
    int accent(String id){return id.equals("mac")?Color.rgb(121,191,255):id.equals("n100")?Color.rgb(184,239,111):Color.rgb(196,167,255);}
    JSONObject host(String id){JSONObject h=hosts.get(id);return h==null?new JSONObject():h;}
    JSONObject obj(JSONObject p,String key){JSONObject o=p.optJSONObject(key);return o==null?new JSONObject():o;}
    double value(JSONObject p,String key){if(p==null||p.isNull(key))return Double.NaN;double v=p.optDouble(key,Double.NaN);return Double.isFinite(v)?v:Double.NaN;}
    String num(double n,String suffix,int digits){return Double.isFinite(n)?String.format(Locale.CHINA,"%."+digits+"f",n)+suffix:"—";}
    String bytes(double b){if(!Double.isFinite(b))return "—";if(b>=1073741824)return num(b/1073741824," GiB",1);if(b>=1048576)return num(b/1048576," MiB",0);if(b>=1024)return num(b/1024," KiB",0);return num(b," B",0);}
    LinearLayout surface(){LinearLayout box=vertical();box.setPadding(dp(16),dp(16),dp(16),dp(16));box.setBackground(background(SURFACE,18));LinearLayout.LayoutParams p=lp(-1,-2);p.setMargins(0,0,0,dp(12));body.addView(box,p);return box;}
    void card(String id){HostCard card=new HostCard(this,id,host(id),history.get(id),previousCpu.getOrDefault(id,Double.NaN),previousMemory.getOrDefault(id,Double.NaN),animateHosts.remove(id),this);card.setId(id.equals("mac")?R.id.card_mac:id.equals("n100")?R.id.card_n100:R.id.card_win11);card.setOnClickListener(v->{detail=id;renderPage();});LinearLayout.LayoutParams params=lp(-1,-2);params.setMargins(0,0,0,dp(10));body.addView(card,params);}
